<?php
declare(strict_types=1);
namespace HaCrm\Services;
use HaCrm\Core\Database;
use PDO;
final class AutomationRunner {
    private PDO $db;
    public function __construct(){ $this->db=Database::connection(); }
    public function run(): void { $this->overdueInvoices();$this->taskReminders();$this->closedWon();$this->sendOutbox(); }
    public function overdueInvoices(): void {
        $q=$this->db->query("SELECT id,tenant_id,invoice_number,grand_total,balance_due,account_id,contact_id FROM invoices WHERE status IN ('Sent','Partially Paid') AND due_date<CURRENT_DATE AND balance_due>0 ORDER BY id LIMIT 100");
        foreach($q->fetchAll() as $i){$event='invoice-overdue:'.$i['id'];$this->db->beginTransaction();try{$this->db->prepare("INSERT IGNORE INTO automation_events(tenant_id,event_key,event_type,entity_type,entity_id) VALUES(?,?,'invoice_overdue','invoice',?)")->execute([$i['tenant_id'],$event,$i['id']]);$lock=$this->db->prepare('SELECT processed_at FROM automation_events WHERE tenant_id=? AND event_key=? FOR UPDATE');$lock->execute([$i['tenant_id'],$event]);if($lock->fetchColumn()){$this->db->commit();continue;}$this->db->prepare("UPDATE invoices SET status='Overdue' WHERE tenant_id=? AND id=? AND status IN ('Sent','Partially Paid')")->execute([$i['tenant_id'],$i['id']]);$taskKey='invoice-overdue-task:'.$i['id'];$this->db->prepare("INSERT IGNORE INTO activities(tenant_id,activity_type,subject,related_type,related_id,due_at,status,priority,description,assigned_to,idempotency_key) SELECT ?, 'Task', ?, 'Deal', NULL,NOW(),'Pending','High',?,u.id,? FROM users u WHERE u.tenant_id=? AND u.role IN ('Admin','Sales Manager') AND u.status='Active' ORDER BY (u.role='Admin') DESC,u.id LIMIT 1")->execute([$i['tenant_id'],'Follow up overdue invoice '.$i['invoice_number'],'Contact the customer regarding the overdue balance.',$taskKey,$i['tenant_id']]);$userQ=$this->db->prepare("SELECT id FROM users WHERE tenant_id=? AND role IN ('Admin','Sales Manager') AND status='Active'");$userQ->execute([$i['tenant_id']]);$notice=$this->db->prepare("INSERT IGNORE INTO notifications(tenant_id,user_id,notification_type,title,body,idempotency_key) VALUES(?,?,'invoice_overdue',?,?,?)");foreach($userQ->fetchAll(PDO::FETCH_COLUMN) as $uid)$notice->execute([$i['tenant_id'],$uid,'Invoice overdue','Invoice '.$i['invoice_number'].' is past due.','invoice-overdue:'.$i['id'].':user:'.$uid]);$email=$this->db->prepare('SELECT c.email FROM contacts c JOIN invoices x ON x.contact_id=c.id WHERE x.tenant_id=? AND x.id=?');$email->execute([$i['tenant_id'],$i['id']]);$recipient=$email->fetchColumn();if($recipient)$this->queueEmail((int)$i['tenant_id'],$event.':email',$recipient,'Payment reminder: invoice '.$i['invoice_number'],'This is a polite reminder that invoice '.$i['invoice_number'].' is overdue. Remaining balance: '.$i['balance_due']);$this->db->prepare('UPDATE automation_events SET processed_at=NOW() WHERE tenant_id=? AND event_key=?')->execute([$i['tenant_id'],$event]);$this->db->commit();}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();error_log('HA CRM overdue invoice '.$i['id'].': '.$e->getMessage());}}
    }
    public function taskReminders(): void {
        $q=$this->db->query("SELECT id,tenant_id,assigned_to,subject FROM activities WHERE status IN ('Pending','In Progress') AND reminder_sent_at IS NULL AND due_at BETWEEN NOW() AND DATE_ADD(NOW(),INTERVAL 30 MINUTE) AND assigned_to IS NOT NULL LIMIT 200");$mark=$this->db->prepare('UPDATE activities SET reminder_sent_at=NOW() WHERE tenant_id=? AND id=? AND reminder_sent_at IS NULL');$ins=$this->db->prepare("INSERT IGNORE INTO notifications(tenant_id,user_id,notification_type,title,body,entity_type,entity_id,idempotency_key) VALUES(?,?,'task_due','Task due soon',?,'activity',?,?)");foreach($q->fetchAll() as $t){$this->db->beginTransaction();try{$mark->execute([$t['tenant_id'],$t['id']]);if(!$mark->rowCount()){$this->db->commit();continue;}$ins->execute([$t['tenant_id'],$t['assigned_to'],$t['subject'].' is due within 30 minutes.',$t['id'],'task-due:'.$t['id']]);$this->db->commit();}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();error_log('HA CRM task reminder '.$t['id'].': '.$e->getMessage());}}
    }
    private function closedWon(): void {
        $q=$this->db->query("SELECT d.* FROM deals d JOIN pipeline_stages s ON s.id=d.stage_id AND s.tenant_id=d.tenant_id WHERE s.is_won=1 AND d.closed_at IS NOT NULL ORDER BY d.id LIMIT 100");foreach($q->fetchAll() as $d){$event='deal-won:'.$d['id'];$this->db->beginTransaction();try{$this->db->prepare("INSERT IGNORE INTO automation_events(tenant_id,event_key,event_type,entity_type,entity_id) VALUES(?,?,'deal_won','deal',?)")->execute([$d['tenant_id'],$event,$d['id']]);$check=$this->db->prepare('SELECT processed_at FROM automation_events WHERE tenant_id=? AND event_key=? FOR UPDATE');$check->execute([$d['tenant_id'],$event]);if($check->fetchColumn()){$this->db->commit();continue;}$exists=$this->db->prepare('SELECT id FROM invoices WHERE tenant_id=? AND automation_key=? LIMIT 1');$exists->execute([$d['tenant_id'],$event]);if(!$exists->fetchColumn()){$number='INV-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$calc=\HaCrm\Domain\BillingCalculator::calculate([['item_name'=>$d['deal_title'],'quantity'=>1,'unit_price'=>$d['amount'],'discount_amount'=>$d['discount_amount'],'tax_rate'=>$d['tax_rate']]]);$this->db->prepare("INSERT INTO invoices(tenant_id,invoice_number,automation_key,deal_id,account_id,contact_id,status,issue_date,due_date,currency,subtotal,global_discount,global_discount_type,taxable_amount,tax_total,grand_total,balance_due,created_by) VALUES(?,?,?,?,?,?,'Draft',?,DATE_ADD(CURRENT_DATE,INTERVAL 30 DAY),?,?,?,?,?,?,?,?,?)")->execute([$d['tenant_id'],$number,$event,$d['id'],$d['account_id'],$d['contact_id'],date('Y-m-d'),$d['currency'],$calc['subtotal'],$calc['global_discount'],$calc['global_discount_type'],$calc['taxable_amount'],$calc['tax_total'],$calc['grand_total'],$calc['grand_total'],$d['created_by']]);$invoice=(int)$this->db->lastInsertId();$item=$calc['items'][0];$this->db->prepare("INSERT INTO invoice_items(tenant_id,invoice_id,item_name,quantity,unit_price,discount_amount,discount_percent,tax_rate,line_subtotal,taxable_amount,tax_amount,item_total) VALUES(?,?,?,1,?,?,?,?,?,?,?,?)")->execute([$d['tenant_id'],$invoice,$item['item_name'],$item['unit_price'],$item['discount_amount'],$item['discount_percent'],$item['tax_rate'],$item['line_subtotal'],$item['taxable_amount'],$item['tax_amount'],$item['item_total']]);}$month=date('Y-m-01');if($d['assigned_to'])$this->db->prepare('INSERT INTO user_monthly_quotas(tenant_id,user_id,month_start,target_amount,won_amount) VALUES(?,?,?,0,?) ON DUPLICATE KEY UPDATE won_amount=won_amount+VALUES(won_amount)')->execute([$d['tenant_id'],$d['assigned_to'],$month,$d['net_value']]);$contact=$this->db->prepare('SELECT email FROM contacts WHERE tenant_id=? AND id=?');$contact->execute([$d['tenant_id'],$d['contact_id']]);$to=$contact->fetchColumn();if($to)$this->queueEmail((int)$d['tenant_id'],$event.':welcome',$to,'Welcome aboard','Thank you for choosing us. Your account team will be in touch shortly.');$this->db->prepare('UPDATE automation_events SET processed_at=NOW() WHERE tenant_id=? AND event_key=?')->execute([$d['tenant_id'],$event]);$this->db->commit();}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();error_log('HA CRM won deal '.$d['id'].': '.$e->getMessage());}}
    }
    private function queueEmail(int $tenant,string $key,string $to,string $subject,string $body): void { $this->db->prepare("INSERT IGNORE INTO email_outbox(tenant_id,event_key,recipient,subject,body) VALUES(?,?,?,?,?)")->execute([$tenant,$key,$to,$subject,$body]); }
    private function sendOutbox(): void { $this->db->exec("UPDATE email_outbox SET status='failed' WHERE status='processing' AND claimed_at<DATE_SUB(NOW(),INTERVAL 15 MINUTE)");$q=$this->db->query("SELECT * FROM email_outbox WHERE status IN ('pending','failed') AND attempts<5 ORDER BY id LIMIT 50");foreach($q->fetchAll() as $m){$this->db->beginTransaction();try{$lock=$this->db->prepare("SELECT status FROM email_outbox WHERE id=? FOR UPDATE");$lock->execute([$m['id']]);$state=$lock->fetchColumn();if(in_array($state,['sent','processing'],true)){$this->db->commit();continue;}$this->db->prepare("UPDATE email_outbox SET status='processing',claimed_at=NOW(),attempts=attempts+1 WHERE id=?")->execute([$m['id']]);$this->db->commit();$sent=Mailer::send((int)$m['tenant_id'],$m['recipient'],$m['subject'],$m['body']);if($sent)$this->db->prepare("UPDATE email_outbox SET status='sent',sent_at=NOW(),claimed_at=NULL,last_error=NULL WHERE id=?")->execute([$m['id']]);else$this->db->prepare("UPDATE email_outbox SET status='failed',claimed_at=NULL,last_error='SMTP not configured' WHERE id=?")->execute([$m['id']]);}catch(\Throwable $e){if($this->db->inTransaction())$this->db->rollBack();$this->db->prepare("UPDATE email_outbox SET status='failed',claimed_at=NULL,last_error=? WHERE id=?")->execute([mb_substr($e->getMessage(),0,500),$m['id']]);error_log('HA CRM mail '.$m['id'].': '.$e->getMessage());}}
    }
}
